using System;
using NUnit.Framework;
using Spacewars.Simulation;
using Spacewars.Runtime;
namespace Spacewars.Tests.EditMode
{
    public sealed partial class NavigationPhysicalBodyTests
    {
        [TestCase(0)][TestCase(3)][TestCase(65)]
        public void BodyArrivalOccupancyDistinctBackingsSharedRowsColdAndPinnedLeaf(int count)
        {
            var publicRows=new NavArrivalOccupant[count];for(int n=0;n<count;n++)publicRows[n]=new NavArrivalOccupant(NavArrivalOccupantKind.Actor,count-n,1,new NavLocation(new NavPoint(n,0),NavLocation.FlatSurface),.3,true,"actor-"+n);var source=new NavArrivalOccupancySnapshot(3,publicRows);
            var hot=new NavigationRetentionBudget();Assert.True(hot.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var birth));var r=birth.OwnedReservation();var ownedRows=new NavArrivalOccupant[count];for(int n=0;n<count;n++)ownedRows[n]=NavArrivalOccupant.CopyOwned(source.Occupants[n],r);var first=NavArrivalOccupancySnapshot.CopyOwned(source,ownedRows,r);var second=NavArrivalOccupancySnapshot.CopyOwned(source,ownedRows,r);Assert.AreNotSame(source.StableKey,first.StableKey);Assert.AreEqual(source.StableKey,first.StableKey);for(int n=0;n<count;n++){Assert.AreSame(first.Occupants[n],second.Occupants[n]);ownedRows[n].StorageRoot.ReleaseOwner();}
            var root=NavRetainedArray<NavOwnedStorage>.Copy(new[]{first.StorageRoot,second.StorageRoot},birth.TryReserve);first.StorageRoot.ReleaseOwner();second.StorageRoot.ReleaseOwner();birth.Attach(root);birth.Commit(root,_=>{});byte[] bytes=CaptureGraph(hot,root);long charge=Unique(root);Assert.AreEqual(charge,hot.PhysicalBytes);root.Release();root=null;first=null;second=null;source=null;publicRows=null;ownedRows=null;Assert.Zero(hot.PhysicalBytes);
            var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavRetainedArray<NavOwnedStorage>)Decode(bytes,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});var a=(NavArrivalOccupancySnapshot)((NavDeclarationStorage)restored[0]).Facade;var b=(NavArrivalOccupancySnapshot)((NavDeclarationStorage)restored[1]).Facade;Assert.AreEqual(3,a.Generation);Assert.AreEqual(count,a.Occupants.Count);var owner=(NavDeclarationStorage)restored[0];var priv=(NavRetainedArray<NavArrivalOccupant>)owner.First;var pub=(NavRetainedArray<NavArrivalOccupant>)owner.Second;Assert.AreNotSame(priv,pub);Assert.AreNotSame(priv.ReadOnlyBacking,pub.ReadOnlyBacking);for(int n=0;n<count;n++){Assert.AreEqual(n+1,a.Occupants[n].ActorId);Assert.AreSame(a.Occupants[n],b.Occupants[n]);Assert.AreSame(priv[n],pub[n]);}Assert.AreEqual(charge,cold.PhysicalBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));
            NavArrivalOccupancySnapshot Born(INavStorageReservation reservation)=>NavArrivalOccupancySnapshot.CopyOwned(a,a.Occupants,reservation);Assert.True(cold.TryOpenScope(NavigationPreparationKind.Admission,1,20,out var trialBirth));var counter=new Refusal(trialBirth,int.MaxValue);var copied=Born(counter);trialBirth.Attach(copied.StorageRoot);int calls=counter.Calls;trialBirth.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);
            for(int nth=1;nth<=calls;nth++){Assert.True(cold.TryOpenScope(NavigationPreparationKind.Admission,1,20+nth,out var rejection));var refusal=new Refusal(rejection,nth);Assert.Throws<InvalidOperationException>(()=>Born(refusal));Assert.AreEqual(nth,refusal.Calls);rejection.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));}
            var foreign=new NavigationRetentionBudget();Assert.True(foreign.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var rejected));Assert.Throws<ArgumentException>(()=>Born(rejected.OwnedReservation()));Assert.Zero(foreign.PhysicalBytes);Assert.AreEqual(NavigationRetentionBudget.ScopeBytes,foreign.HeldBytes);rejected.Discard();NavOwnedStorage pin=count>0?a.Occupants[0].StorageRoot:null;pin?.Retain();restored.Release();restored=null;a=null;b=null;priv=null;pub=null;owner=null;if(pin!=null){Assert.AreEqual(Unique(pin),cold.PhysicalBytes);Assert.AreEqual(1,((NavArrivalOccupant)((NavDeclarationStorage)pin).Facade).ActorId);pin.Release();pin=null;}Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
            var counted=new NavigationRetentionBudget();Assert.True(counted.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var scope));var all=new Refusal(scope,int.MaxValue);var trial=Decode(bytes,all);scope.Attach(trial);int allocations=all.Calls;scope.Discard();Assert.Zero(counted.PhysicalBytes);
            for(int nth=1;nth<=allocations;nth++){var bad=new NavigationRetentionBudget();Assert.True(bad.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rejection));var refusal=new Refusal(rejection,nth);Assert.Throws<InvalidOperationException>(()=>Decode(bytes,refusal));Assert.AreEqual(nth,refusal.Calls);rejection.Discard();Assert.Zero(bad.PhysicalBytes);Assert.Zero(bad.HeldBytes);Assert.Zero(bad.ActiveScopes);}
        }
    }
}
